WeakLaneCombination LaneCombinations::PickWeak(std::uint64_t pSelect) {
    return mWeak[pSelect % mWeakCount];
}

NormalLaneCombination LaneCombinations::PickNormal(std::uint64_t pSelect) {
    return mNormal[pSelect % mNormalCount];
}

StrongLaneCombination LaneCombinations::PickStrong(std::uint64_t pSelect) {
    return mStrong[pSelect % mStrongCount];
}
